parameters.jsCode:
// The lead as it arrived in this workflow
const lead = $('Receive Leads').item.json;
const found = $json.output || {};

// Clean a text value
function clean(value) {
  return String(value || '').trim();
}

// An empty companyFacts means the research failed.
// We do not stop here: Outreach sees the empty facts and rejects the lead,
// so it is not picked again on every run.
const facts = clean(found.companyFacts);

const newEmail = clean(found.contactEmail).toLowerCase();
const newEmailSource = clean(found.emailSourceUrl);
const newOfferTitle = clean(found.jobOfferTitle);
const newOfferUrl = clean(found.jobOfferUrl);

// An address is only replaced together with its source page, so they never get mixed
const useNewEmail = newEmail !== '' && newEmailSource !== '';
// The same for the job offer title and its link
const useNewOffer = newOfferTitle !== '' && newOfferUrl !== '';

// Return the same lead with the research added
return {
  json: {
    ...lead,
    companyFacts: facts,
    contactFacts: clean(found.contactFacts),
    contactEmail: useNewEmail ? newEmail : lead.contactEmail,
    emailSourceUrl: useNewEmail ? newEmailSource : lead.emailSourceUrl,
    jobOfferTitle: useNewOffer ? newOfferTitle : lead.jobOfferTitle,
    jobOfferUrl: useNewOffer ? newOfferUrl : lead.jobOfferUrl,
    emailVerified: false
  }
};
